// MeshServiceHandler is an implementation of the agentmesh.v1.MeshService service.
type MeshServiceHandler interface {
	// The handshake: who the daemon is and what it supports. A connection is ready once this answers.
	Hello(context.Context, *connect.Request[v1.HelloRequest]) (*connect.Response[v1.HelloResponse], error)
	StartRun(context.Context, *connect.Request[v1.StartRunRequest]) (*connect.Response[v1.StartRunResponse], error)
	ListRuns(context.Context, *connect.Request[v1.ListRunsRequest]) (*connect.Response[v1.ListRunsResponse], error)
	// Start an agent in a repo's new worktree. A device starts any role, a root workers and read-only agents, a
	// worker only read-only agents (askers, reviewers).
	SpawnAgent(context.Context, *connect.Request[v1.SpawnAgentRequest]) (*connect.Response[v1.SpawnAgentResponse], error)
	ListAgents(context.Context, *connect.Request[v1.ListAgentsRequest]) (*connect.Response[v1.ListAgentsResponse], error)
	GetAgent(context.Context, *connect.Request[v1.GetAgentRequest]) (*connect.Response[v1.GetAgentResponse], error)
	// Stop an agent's process (its whole process group). A device stops any agent, an agent only its children.
	StopAgent(context.Context, *connect.Request[v1.StopAgentRequest]) (*connect.Response[v1.StopAgentResponse], error)
	// Approve an agent's plan: store the answer and move it to its execution tier (or model) by reopening its own
	// conversation without the planning deny list. Only its parent or a device, and only when its newest report
	// since its last task or answer is a plan.
	ApproveAgent(context.Context, *connect.Request[v1.ApproveAgentRequest]) (*connect.Response[v1.ApproveAgentResponse], error)
	// Move an agent to another tier, model or effort, or to the next model of its chain (a quota), by reopening
	// its own conversation. A move asked for mid-turn runs at its next IDLE.
	SwitchAgent(context.Context, *connect.Request[v1.SwitchAgentRequest]) (*connect.Response[v1.SwitchAgentResponse], error)
	// Reopen a stopped agent's conversation, with a new task or as it was.
	ResumeAgent(context.Context, *connect.Request[v1.ResumeAgentRequest]) (*connect.Response[v1.ResumeAgentResponse], error)
	// Stop an agent's process on purpose and keep its conversation: RETIRED, its token revoked, its worktree and
	// branch kept. A message to it, or ResumeAgent, brings it back. Its parent or a device.
	RetireAgent(context.Context, *connect.Request[v1.RetireAgentRequest]) (*connect.Response[v1.RetireAgentResponse], error)
	// Change a run's title. A root may rename its own run; a device any.
	RenameRun(context.Context, *connect.Request[v1.RenameRunRequest]) (*connect.Response[v1.RenameRunResponse], error)
	// Ask the user's app to show a view (an agent's chat or terminal, the settings, a run): sent to the apps connected now,
	// which show it as a toast the user opens or dismisses (and switch by themselves only when the user turned `app.open_views` on).
	// An agent may ask once in 10 seconds.
	OpenView(context.Context, *connect.Request[v1.OpenViewRequest]) (*connect.Response[v1.OpenViewResponse], error)
	// Stop a run: retire every agent in it and close it. A clean worktree is removed, and its branch with it unless
	// it moved past the commit it started at, or was pushed; a worktree with uncommitted changes stays.
	StopRun(context.Context, *connect.Request[v1.StopRunRequest]) (*connect.Response[v1.StopRunResponse], error)
	// Store a message for an agent and ring its doorbell. An agent sends only to its parent or its children.
	SendMessage(context.Context, *connect.Request[v1.SendMessageRequest]) (*connect.Response[v1.SendMessageResponse], error)
	// The tasks held for a task that is not reported done yet (`SendMessage` with `after`), oldest first. A lead reads its
	// own run's.
	ListHeldTasks(context.Context, *connect.Request[v1.ListHeldTasksRequest]) (*connect.Response[v1.ListHeldTasksResponse], error)
	// Drop a held task: it is never sent.
	CancelHeldTask(context.Context, *connect.Request[v1.CancelHeldTaskRequest]) (*connect.Response[v1.CancelHeldTaskResponse], error)
	// The calling agent's messages; unread ones are marked read unless peek is set.
	ReadInbox(context.Context, *connect.Request[v1.ReadInboxRequest]) (*connect.Response[v1.ReadInboxResponse], error)
	// Make a running Claude Code session the run's root, in place: the session keeps its terminal, and its `mesh`
	// calls act as the root. The run's own root, when it has one, is retired and this session takes its place (its
	// id, name, mailbox and workers). Needs the session to take cross-session frames (`crossSessionInbound`
	// accept in the user's own Claude settings: mesh never edits them). `mesh adopt` fills `pid` from the session
	// it runs in.
	AdoptSession(context.Context, *connect.Request[v1.AdoptSessionRequest]) (*connect.Response[v1.AdoptSessionResponse], error)
	// A change worker's work at a glance: its branch's commits past the base, the diff stat, whether the tip is
	// pushed and the worktree clean, and its PRs with their checks (read from GitHub now). One call for what the
	// root otherwise fetches, diffs and lists by hand.
	CheckAgent(context.Context, *connect.Request[v1.CheckAgentRequest]) (*connect.Response[v1.CheckAgentResponse], error)
	// The stored messages of a run, oldest first, for a device or a root to read (ReadInbox is an agent's own
	// mailbox). A page ends at `limit`; `more` says there are further messages after the last one, whose id is
	// the next page's `after_id`.
	ListMessages(context.Context, *connect.Request[v1.ListMessagesRequest]) (*connect.Response[v1.ListMessagesResponse], error)
	// What waits on the user (what `bin/mesh status` calls waiting rows, for a person): a plan or a question sent
	// to an open run's lead that nobody has answered since, from an agent that is still there to hear the answer,
	// and every agent stopped at a prompt in its terminal. Oldest first, plans and questions before prompts. A
	// lead reads its own run's.
	ListWaiting(context.Context, *connect.Request[v1.ListWaitingRequest]) (*connect.Response[v1.ListWaitingResponse], error)
	// The event log from a cursor, then live. The first message is a Snapshot or a Resumed; only an End message
	// ends the stream, so a client resumes from its cursor after any other close.
	SubscribeEvents(context.Context, *connect.Request[v1.SubscribeEventsRequest], *connect.ServerStream[v1.SubscribeEventsResponse]) error
	// The host's settings (the policy: tiers, reviewers, caps, …) with their defaults and schemas, every one whose
	// key starts with the prefix. Agents read the policy they run under.
	ListSettings(context.Context, *connect.Request[v1.ListSettingsRequest]) (*connect.Response[v1.ListSettingsResponse], error)
	// Set a setting. The value must fit its schema; a key no setting has is NotFound.
	SetSetting(context.Context, *connect.Request[v1.SetSettingRequest]) (*connect.Response[v1.SetSettingResponse], error)
	// Carry bin/mesh's policy file (`~/.config/agent-mesh.json`) over: each leaf it names that this host has (or
	// maps: `repos_dir`, `peers_dir`, `copilot_model`) is stored as a setting, except one already set unless
	// `overwrite`. The file is only read; a key that can't be imported is reported and skipped.
	ImportSettings(context.Context, *connect.Request[v1.ImportSettingsRequest]) (*connect.Response[v1.ImportSettingsResponse], error)
	// Put a setting back to its default.
	ResetSetting(context.Context, *connect.Request[v1.ResetSettingRequest]) (*connect.Response[v1.ResetSettingResponse], error)
	// Reset the root's context (`mesh reset`): at a quiet prompt it relaunches lean or `/clear`s, then rings the
	// bootstrap text. Acts on the caller's own run's root.
	ResetRoot(context.Context, *connect.Request[v1.ResetRootRequest]) (*connect.Response[v1.ResetRootResponse], error)
	// Each change worker's pull requests with their state and checks, read from GitHub (cached two minutes), and
	// the work evidence (commits, pushed, dirty) of a worker with none.
	ListPullRequests(context.Context, *connect.Request[v1.ListPullRequestsRequest]) (*connect.Response[v1.ListPullRequestsResponse], error)
	// Hold a pull request's merge, or release it: a root never merges a held PR (ORCHESTRATE). The hold is the user's
	// brake on one PR, at any autonomy level; it is kept by the PR's url (outliving every record of it) and shown by
	// ListPullRequests. A root may hold a PR of its own run, and may not release one: only the user does.
	HoldPullRequest(context.Context, *connect.Request[v1.HoldPullRequestRequest]) (*connect.Response[v1.HoldPullRequestResponse], error)
	// The repositories this host can start work in: the git folders under the `repos.dir` folders and every repo
	// an agent has worked in, each with its default branch and branches; with `repo` set, that one with its open
	// pull requests (read from GitHub) too.
	ListProjects(context.Context, *connect.Request[v1.ListProjectsRequest]) (*connect.Response[v1.ListProjectsResponse], error)
	// What a root (or any agent) needs to rebuild its picture of the run: the root card, notes, status, unread mail
	// headers and the last reset. Marks nothing read.
	GetBrief(context.Context, *connect.Request[v1.GetBriefRequest]) (*connect.Response[v1.GetBriefResponse], error)
	// A hook of the calling agent's CLI fired. Called by `mesh hook`, never by hand.
	ReportHook(context.Context, *connect.Request[v1.ReportHookRequest]) (*connect.Response[v1.ReportHookResponse], error)
	// A one-time ticket for an agent's terminal WebSocket. Input is granted only with the terminal.input right.
	OpenTerminal(context.Context, *connect.Request[v1.OpenTerminalRequest]) (*connect.Response[v1.OpenTerminalResponse], error)
	// Start a plain login shell in a project's folder, on the host's terminal host (it survives an app restart and a
	// daemon restart). Not an agent: no run, no row, no confinement. Needs the `terminal.input` right, and a project the
	// host knows (a folder of `repos.dir`, or a repo an agent worked in: what `ListProjects` draws on).
	OpenShell(context.Context, *connect.Request[v1.OpenShellRequest]) (*connect.Response[v1.OpenShellResponse], error)
	// The shells that are running (or exited and not yet seen to), oldest first.
	ListShells(context.Context, *connect.Request[v1.ListShellsRequest]) (*connect.Response[v1.ListShellsResponse], error)
	// End a shell: SIGHUP, as closing a terminal window does (the shell passes it to its background jobs), then SIGTERM and SIGKILL after 3 s if it is still there; the host forgets it. A ticket already issued for it stops working.
	CloseShell(context.Context, *connect.Request[v1.CloseShellRequest]) (*connect.Response[v1.CloseShellResponse], error)
	// An agent's conversation as its CLI recorded it, for the chat view: the prompts, replies and tool calls, a page at
	// a time. Only for a CLI whose record the adapter can read (Claude Code); others answer `supported: false`.
	ReadTranscript(context.Context, *connect.Request[v1.ReadTranscriptRequest]) (*connect.Response[v1.ReadTranscriptResponse], error)
	// The commands an agent's CLI accepts when typed at its prompt, with descriptions and argument hints, for the
	// composer's `/` completion: the CLI's built-ins and what it loads for this agent (the repo's and the user's
	// commands, skills, plugins). Read from the CLI where it can say (Claude Code), else from a table of its
	// built-ins plus the files it reads.
	ListAgentCommands(context.Context, *connect.Request[v1.ListAgentCommandsRequest]) (*connect.Response[v1.ListAgentCommandsResponse], error)
	// The prompt Claude Code suggests next (grey text in its empty input box after a turn), read from the agent's
	// screen. Empty when there is none, the agent is not at its prompt, or its CLI has no such feature.
	GetPromptSuggestion(context.Context, *connect.Request[v1.GetPromptSuggestionRequest]) (*connect.Response[v1.GetPromptSuggestionResponse], error)
	// Type a prompt into the agent's running CLI, as the user would in its terminal (the chat view's composer). Never
	// a second process on the conversation, and never a mesh message: it is the user's own words, so only a device
	// with the terminal.input right may. Typed at once when the agent is at its prompt with an empty input box; else
	// queued (the answer's `queued`) and typed at its next idle. Refused only for an agent with no terminal.
	PromptAgent(context.Context, *connect.Request[v1.PromptAgentRequest]) (*connect.Response[v1.PromptAgentResponse], error)
	// The prompts the user sent an agent that wait to be typed: sent while it worked, started, waited at a prompt or had
	// a draft in its box (`PromptAgent` queues them), typed one at a time at its next idle, oldest first.
	ListPrompts(context.Context, *connect.Request[v1.ListPromptsRequest]) (*connect.Response[v1.ListPromptsResponse], error)
	// Take back a queued prompt before it is typed (the chat's Up arrow): the prompt is returned, to edit or drop. Refused
	// once the daemon has started typing it, so a prompt is either withdrawn or typed, never both.
	WithdrawPrompt(context.Context, *connect.Request[v1.WithdrawPromptRequest]) (*connect.Response[v1.WithdrawPromptResponse], error)
	// Type a queued prompt now although the agent's input box holds a draft (its `held` is "draft"): clears the box, as Ctrl-U
	// does, and types the prompt. For a draft the caller was shown (`QueuedPrompt.held_text`) and confirmed to discard: refused
	// when the box holds anything else by now, when someone is typing in the terminal, or when the agent is not at its prompt.
	SendPromptAnyway(context.Context, *connect.Request[v1.SendPromptAnywayRequest]) (*connect.Response[v1.SendPromptAnywayResponse], error)
	// Interrupt an agent's turn, as Esc does in its terminal: the CLI stops what it is doing and waits for a prompt. Only
	// for a CLI whose interrupt key the adapter knows. A root may interrupt an agent of its own run.
	InterruptAgent(context.Context, *connect.Request[v1.InterruptAgentRequest]) (*connect.Response[v1.InterruptAgentResponse], error)
	// Take an agent's conversation back to before one of its prompts (Claude Code's Esc Esc, conversation only): the
	// daemon writes a copy of its conversation cut before that prompt, under a new session id, and reopens the same
	// agent on it. Files, commits and sent mesh messages stay as they are. Refused while the agent works (interrupt it
	// first) and for a CLI whose conversation the daemon can't cut. The prompt's text is returned, to edit and send again.
	RewindAgent(context.Context, *connect.Request[v1.RewindAgentRequest]) (*connect.Response[v1.RewindAgentResponse], error)
	// Store an image for a prompt to an agent (the chat's paste, drop or file button) in its run's folder on the host,
	// which may be another machine: the path returned goes in the prompt, and the CLI reads the file with its own
	// file tool. PNG, JPEG, GIF or WebP, at most 10 MB.
	AddAttachment(context.Context, *connect.Request[v1.AddAttachmentRequest]) (*connect.Response[v1.AddAttachmentResponse], error)
	// Create a one-time pairing token and QR/link payload for pairing a new device. Only the host's own device, or
	// the root of the setup run (`StartSetup`), may call this.
	CreatePairing(context.Context, *connect.Request[v1.CreatePairingRequest]) (*connect.Response[v1.CreatePairingResponse], error)
	// List paired devices. Only the host's own device, or the root of the setup run, may call this.
	ListDevices(context.Context, *connect.Request[v1.ListDevicesRequest]) (*connect.Response[v1.ListDevicesResponse], error)
	// Revoke a paired device's token and close its active streams. Only the host's own device may call this.
	RevokeDevice(context.Context, *connect.Request[v1.RevokeDeviceRequest]) (*connect.Response[v1.RevokeDeviceResponse], error)
	// Revoke the calling device's own pairing and close its streams: how a paired app unpairs itself. The host's own
	// device can't be revoked.
	RevokeSelf(context.Context, *connect.Request[v1.RevokeSelfRequest]) (*connect.Response[v1.RevokeSelfResponse], error)
	// Register the calling device's UnifiedPush endpoint (WebPush, RFC 8030/8291) for notifications with the app
	// closed. One endpoint per device: a new one replaces the old, and an endpoint another device held moves here.
	// A device registers only itself; revoking the device deletes it.
	RegisterPush(context.Context, *connect.Request[v1.RegisterPushRequest]) (*connect.Response[v1.RegisterPushResponse], error)
	// Remove a device's push endpoint: the caller's own, or (the host's own device only) another device's.
	UnregisterPush(context.Context, *connect.Request[v1.UnregisterPushRequest]) (*connect.Response[v1.UnregisterPushResponse], error)
	// Send a test notification to a device's push endpoint: the caller's own, or (the host's own device only)
	// another device's. Answers once the push service took it, or with its error.
	TestPush(context.Context, *connect.Request[v1.TestPushRequest]) (*connect.Response[v1.TestPushResponse], error)
	// Start the first-run setup agent, or return the one that is running (a retired one is resumed): a lead agent in a
	// run flagged `setup`, in a scratch repo of the host's own, that follows `protocol/SETUP.md` of the share folder.
	// The apps call it once connected; `mesh setup` does the same.
	StartSetup(context.Context, *connect.Request[v1.StartSetupRequest]) (*connect.Response[v1.StartSetupResponse], error)
	// The host's built-in Tailscale node (`meshd --tailscale`): its state, the login URL while it needs one, and its
	// tailnet addresses. Only the host's own device, or the root of the setup run, may call this: the login URL
	// attaches the node to whichever tailnet opens it.
	TailnetStatus(context.Context, *connect.Request[v1.TailnetStatusRequest]) (*connect.Response[v1.TailnetStatusResponse], error)
	// Quota usage for Claude and agy, what each agy tier would start on, and the reserve threshold.
	GetUsage(context.Context, *connect.Request[v1.GetUsageRequest]) (*connect.Response[v1.GetUsageResponse], error)
	// Let a run go on past the quota reserve (`off`), hold it to it again (`on`), or read its state.
	SetReserve(context.Context, *connect.Request[v1.SetReserveRequest]) (*connect.Response[v1.SetReserveResponse], error)
	// Ask a question, or have a pull request reviewed. A fresh read-only agent starts, or an existing one is asked
	// again; a round of reviewers is collected into one answers file and one message to you.
	Ask(context.Context, *connect.Request[v1.AskRequest]) (*connect.Response[v1.AskResponse], error)
	// Record the judge's verdict on one reviewer's findings of a PR's newest round: the PR author's (a worker: its
	// own newest round, never one the root asked) or the root's (which replaces it).
	RecordVerdict(context.Context, *connect.Request[v1.RecordVerdictRequest]) (*connect.Response[v1.RecordVerdictResponse], error)
	// List the asks and review rounds of a run.
	ListAsks(context.Context, *connect.Request[v1.ListAsksRequest]) (*connect.Response[v1.ListAsksResponse], error)
	// The standing peers: cloned projects, each a read-only asker that keeps its conversation across runs.
	ListPeers(context.Context, *connect.Request[v1.ListPeersRequest]) (*connect.Response[v1.ListPeersResponse], error)
	// Register a project as a peer: clone a URL (or use a clone that exists) and give it a worktree of its own.
	AddPeer(context.Context, *connect.Request[v1.AddPeerRequest]) (*connect.Response[v1.AddPeerResponse], error)
	// Change what a peer, or a group of peers, is said to be for.
	EditPeer(context.Context, *connect.Request[v1.EditPeerRequest]) (*connect.Response[v1.EditPeerResponse], error)
	// Remove a peer from the registry and its worktree (and, if asked, the clone the daemon made).
	RemovePeer(context.Context, *connect.Request[v1.RemovePeerRequest]) (*connect.Response[v1.RemovePeerResponse], error)
	// Register the peers of bin/mesh's peers.json (read only), each with its conversation (session, folder, last ask) unless
	// that may still be running in bin/mesh or `unbriefed` is set; a registered peer never asked is given its conversation too.
	ImportPeers(context.Context, *connect.Request[v1.ImportPeersRequest]) (*connect.Response[v1.ImportPeersResponse], error)
	// Tokens per agent, kind, model and phase from session files (Claude, agy and OpenCode alike), plus reviewer verdicts.
	// The total is input + cache writes + output; cache reads are listed apart. Dollars are Claude's at API prices, context only.
	GetCost(context.Context, *connect.Request[v1.GetCostRequest]) (*connect.Response[v1.GetCostResponse], error)
	// Check listed model families against the tiers: flag new or retired families, and acknowledge decided ones.
	CheckModels(context.Context, *connect.Request[v1.CheckModelsRequest]) (*connect.Response[v1.CheckModelsResponse], error)
	// What a spawn of a kind and tier would run now: the model and effort, and the tier's chain with each model's
	// standing (held at a limit, at the quota reserve). The same pick a spawn makes; it starts nothing.
	ResolveModel(context.Context, *connect.Request[v1.ResolveModelRequest]) (*connect.Response[v1.ResolveModelResponse], error)
	// Find which run branches with commits conflict with their base or each other, and which workers share files.
	CheckConflicts(context.Context, *connect.Request[v1.CheckConflictsRequest]) (*connect.Response[v1.CheckConflictsResponse], error)
	// List what a lean Claude session starts without (tools, skills, plugins, MCP servers, connectors) and what it
	// added back.
	ListTools(context.Context, *connect.Request[v1.ListToolsRequest]) (*connect.Response[v1.ListToolsResponse], error)
	// Add cut tools, skills, plugins, MCP servers, `anthropic-skills`, or `claude.ai` connectors back to a lean
	// Claude session by reopening the same conversation at its next idle.
	AddTools(context.Context, *connect.Request[v1.AddToolsRequest]) (*connect.Response[v1.AddToolsResponse], error)
	// An agent's hook asks for the answer to a permission prompt its CLI is about to show: held until the agent's
	// parent decides (`mesh permission`) or the wait runs out, which leaves the prompt to the person at the terminal.
	RequestPermission(context.Context, *connect.Request[v1.RequestPermissionRequest]) (*connect.Response[v1.RequestPermissionResponse], error)
	// Answer a worker's pending permission prompt: allow it, or deny it with a reason the worker reads.
	DecidePermission(context.Context, *connect.Request[v1.DecidePermissionRequest]) (*connect.Response[v1.DecidePermissionResponse], error)
	// The permission prompts waiting for an answer: the caller's own agents' (a device: every run's).
	ListPermissions(context.Context, *connect.Request[v1.ListPermissionsRequest]) (*connect.Response[v1.ListPermissionsResponse], error)
	// List the user's MCP servers, which load always, which are exclusive, and who currently holds each exclusive one.
	ListMCPServers(context.Context, *connect.Request[v1.ListMCPServersRequest]) (*connect.Response[v1.ListMCPServersResponse], error)
	// Create a run worktree with no agent in it (e.g. for integration), cleaned up when the run stops.
	CreateWorktree(context.Context, *connect.Request[v1.CreateWorktreeRequest]) (*connect.Response[v1.CreateWorktreeResponse], error)
	// The run's events and messages as a timeline (sends, nudges, alerts, swaps...).
	StreamLog(context.Context, *connect.Request[v1.StreamLogRequest], *connect.ServerStream[v1.StreamLogResponse]) error
	// What an agent's worktree holds that isn't on a remote yet: the files changed since the commit its branch started at,
	// uncommitted work, and commits no remote branch has.
	GetAgentChanges(context.Context, *connect.Request[v1.GetAgentChangesRequest]) (*connect.Response[v1.GetAgentChangesResponse], error)
	// An agent's progress as its CLI's record shows it: the plan it keeps (Claude's TodoWrite list) and how much context
	// its conversation holds. Only a CLI whose record the daemon reads has any (Claude Code).
	GetAgentProgress(context.Context, *connect.Request[v1.GetAgentProgressRequest]) (*connect.Response[v1.GetAgentProgressResponse], error)
	// What every idle agent waits on, in one call (`GetAgentProgress.wait` for each, sharing the reads): the apps' sidebar,
	// dock and tree word an idle agent by it, and count one on its own background job or declared wait as live. Only
	// agents that are idle now (not archived); a root reads its own run's unless it names another.
	ListAgentWaits(context.Context, *connect.Request[v1.ListAgentWaitsRequest]) (*connect.Response[v1.ListAgentWaitsResponse], error)
	// Archive an agent: retire it and remove its worktree, keeping its branch. Refused while the worktree has uncommitted
	// changes, and, without `force`, while the branch has commits no remote branch has. A message to the agent or
	// ResumeAgent brings it back: the worktree is made again from the branch.
	ArchiveAgent(context.Context, *connect.Request[v1.ArchiveAgentRequest]) (*connect.Response[v1.ArchiveAgentResponse], error)
	// Open a path of an agent's worktree in the host's editor (the `editor.command` setting, run without a shell with the
	// path as one argument). The host's own device only: it runs a program on the host's machine.
	OpenInEditor(context.Context, *connect.Request[v1.OpenInEditorRequest]) (*connect.Response[v1.OpenInEditorResponse], error)
	// Turn the built-in Tailscale node on or off. Takes effect at the next start of meshd: when it runs under a service
	// manager it restarts itself. The host's own device only.
	SetTailnet(context.Context, *connect.Request[v1.SetTailnetRequest]) (*connect.Response[v1.SetTailnetResponse], error)
	// Re-ring an agent that has unread mail now, through the doorbell delivery path and draft guard.
	RingAgent(context.Context, *connect.Request[v1.RingAgentRequest]) (*connect.Response[v1.RingAgentResponse], error)
	// Attach to a running agent's terminal, or reopen a stopped agent's conversation in your terminal outside any run.
	// Intentionally write: false (no RequestMeta): one-time terminal tickets must not be stored or replayed from
	// mutations, and standalone worktree preparation before exec is idempotent.
	OpenAgent(context.Context, *connect.Request[v1.OpenAgentRequest]) (*connect.Response[v1.OpenAgentResponse], error)
}

// NewMeshServiceHandler builds an HTTP handler from the service implementation. It returns the path
